import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { uploadMaterial } from "../handlers/uploadMaterial";
import type { ApiError } from "../runtime/client";
import type { SpaceDiscussionEntityType } from "../types/SpaceDiscussionEntityType";
import type { SpacePartition } from "../types/SpacePartition";
import type { UploadMaterialRequest } from "../types/UploadMaterialRequest";

type Data = Awaited<ReturnType<typeof uploadMaterial>>;
type Vars = { spaceId: SpacePartition; discussionId: SpaceDiscussionEntityType; req: UploadMaterialRequest };

export function useUploadMaterial(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => uploadMaterial(vars.spaceId, vars.discussionId, vars.req),
    ...options,
  });
}
